      --ink-soft: #a6b0a9;
      --ink-faint: #7c867f;
      --rule: #2b332e;
      --accent: #83cda5;
      --accent-soft: #1b2a22;
      --flag: #e3ad50;
      --flag-soft: #2c2314;
    }
  }

  :root[data-theme="dark"] {
    --ground: #0e1211;
    --raised: #171d1a;
    --ink: #e7ebe8;
    --ink-soft: #a6b0a9;
    --ink-faint: #7c867f;
    --rule: #2b332e;
    --accent: #83cda5;
    --accent-soft: #1b2a22;
    --flag: #e3ad50;
    --flag-soft: #2c2314;
  }

  :root[data-theme="light"] {
    --ground: #f4f6f4;
    --raised: #ffffff;
    --ink: #16191a;
    --ink-soft: #565d58;
